action.command:
cd /workspace
cat > /tmp/diag2.sql <<'SQL'
SHOW DATABASES;
SELECT DATABASE();
SHOW TABLES;
SQL
runuser -u dev -- ddev exec mysql -udb -pdb db < /tmp/diag2.sql 2>/dev/null > /tmp/tables.txt; grep -c "" /tmp/tables.txt; grep -in "system\|database" /tmp/tables.txt | head; echo "==="; cat /tmp/tables.txt

